"""Render a complete annotated HTML: English + translation left, paragraph notes right."""
import base64, html, json, mimetypes, sys
from pathlib import Path
from validate_note import validate
def e(s):return html.escape(str(s),quote=True)
def p(s):return ''.join('<p>'+e(x).replace('\n','<br>')+'</p>' for x in s.split('\n\n') if x.strip())
LABELS={'thesis':'核心论点 / thesis','term':'关键概念 / 术语','evidence':'实证证据 / 数据','concession':'让步 / 反驳处理','method':'方法论说明'}
STYLE='''
:root{--navy:#10263f;--paper:#f7f4ec;--white:#fffdf8;--ink:#253244;--line:#ded9ce;--muted:#687383;--thesis:#f2d66d;--term:#e98b82;--evidence:#83b9e8;--concession:#8bc59b;--method:#b6a0dc}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:94px}body{margin:0;background:var(--paper);color:var(--ink);font-family:Inter,'Microsoft YaHei',system-ui,sans-serif;line-height:1.8}a{color:#245b83;text-decoration:none}a:hover{text-decoration:underline}button,select{font:inherit;cursor:pointer}a:focus-visible,button:focus-visible,select:focus-visible{outline:3px solid #b38b38;outline-offset:4px}.site-nav{display:flex;justify-content:space-between;gap:22px;align-items:center;padding:14px max(24px,calc((100vw - 1440px)/2));background:#fffdf8;border-bottom:1px solid var(--line);font-size:12px}.site-nav strong{letter-spacing:.13em}.site-nav div{display:flex;gap:24px}.paper-top{background:var(--navy);color:#f7f5ef;padding:30px max(24px,calc((100vw - 1440px)/2));border-bottom:4px solid #c8b77d}.kicker{font-size:11px;letter-spacing:.14em;color:#c4d2dd}h1{font-size:clamp(25px,3vw,38px);line-height:1.4;margin:12px 0;font-weight:600}.course{color:#d1d9e1;font-size:14px}.citation{font-size:12px;color:#c8d3dc;max-width:1150px}.meta{display:flex;gap:9px;flex-wrap:wrap;margin:15px 0}.meta span,.paper-actions a,.paper-actions button,.paper-actions select{border:1px solid #ffffff44;padding:5px 10px;font-size:11px;color:#eef2f3;background:transparent;border-radius:3px}.paper-actions select{background:var(--navy)}.paper-actions{display:flex;flex-wrap:wrap;gap:10px;align-items:center}.legend{display:flex;gap:9px 20px;flex-wrap:wrap;margin-top:22px;padding-top:16px;border-top:1px solid #ffffff30;font-size:12px}.legend span{display:flex;gap:7px;align-items:center}.swatch{width:11px;height:11px;display:inline-block;border-radius:2px}.section-nav{position:sticky;top:0;z-index:20;background:#fffdf8f5;backdrop-filter:blur(10px);border-bottom:1px solid var(--line);box-shadow:0 3px 12px #19263208}.nav-inner{display:flex;max-width:1488px;margin:auto;padding:0 24px;gap:6px;overflow-x:auto}.section-nav a{white-space:nowrap;font-size:12px;color:#536174;border-bottom:2px solid transparent;padding:13px 11px}.section-nav a.active{border-color:#b69b54;color:var(--navy)}main{max-width:1488px;padding:28px 24px 60px;margin:auto}.notice{background:#f0ece2;border:1px solid #e1dacb;border-left:3px solid #b69b54;padding:13px 17px;font-size:12px;color:#655f52;margin-bottom:24px}.overview{font-size:15px;line-height:1.95}.section-heading{display:flex;justify-content:space-between;gap:20px;align-items:baseline;border-bottom:1px solid #cfc8b9;margin:40px 0 16px;padding-bottom:10px}.section-heading h2{font-size:22px;line-height:1.5;color:var(--navy);margin:0}.section-heading p{font-size:11px;color:var(--muted);margin:0}.column-head,.pair{display:grid;grid-template-columns:minmax(0,1.18fr) minmax(300px,.82fr);gap:20px}.column-head{font-size:11px;color:var(--muted);letter-spacing:.08em;padding:0 5px;margin-bottom:12px}.pair{align-items:start;margin-bottom:22px;scroll-margin-top:85px}.left-card{min-width:0;border:1px solid #e5e0d6;background:var(--white);border-radius:5px;box-shadow:0 7px 22px #1a273609;overflow:hidden}.passage-top{padding:20px 23px}.passage-label{display:flex;justify-content:space-between;gap:12px;font-size:10px;color:#8a887f;letter-spacing:.05em;margin-bottom:10px}.passage-title{font-size:15px;color:#24364a;font-weight:600;line-height:1.6;margin:0 0 12px}.english{font-family:Georgia,'Times New Roman',serif;font-size:16px;line-height:1.95;overflow-wrap:anywhere}.english p{margin:0 0 12px}.english p:last-child{margin-bottom:0}.translation{border-top:1px solid #d9d4ca;background:#f0ece2;padding:15px 23px 17px 25px;position:relative;font-size:14px;line-height:1.95;color:#4b4a43}.translation:before{content:'';position:absolute;left:0;top:15px;bottom:15px;width:2px;background:#b8a77e}.translation-label{display:block;font-size:10px;letter-spacing:.1em;color:#8a806b;margin-bottom:7px;font-weight:600}.translation p{margin:0 0 12px}.translation p:last-child{margin-bottom:0}.annotation{border:1px solid #e4dfd5;border-left:4px solid var(--accent,#8a9bad);border-radius:5px;background:#fffdf9;padding:18px 20px;box-shadow:0 5px 18px #1a273607;min-width:0}.annotation .function{font-size:12px;color:#43556a;font-weight:600;padding-bottom:12px;border-bottom:1px solid #ece6db}.annotation h4{font-size:11px;color:#7c7e77;margin:15px 0 5px;letter-spacing:.04em}.annotation p{font-size:13px;line-height:1.95;color:#4f5965;margin:0 0 10px}.explain{border-top:1px dashed #d8d1c4;margin-top:14px;padding-top:1px}.explain h4{color:#5c5474}.annotation .source-note{font-size:10px;color:#8b8f91;overflow-wrap:anywhere;margin-top:14px}mark{color:inherit;padding:0 .09em;border-radius:2px;box-decoration-break:clone;-webkit-box-decoration-break:clone}mark.thesis{background:#f2d66db8}mark.term{background:#e98b8275}mark.evidence{background:#83b9e87a}mark.concession{background:#8bc59b80}mark.method{background:#b6a0dc80}figure{margin:0;padding:19px 23px;border-top:1px solid var(--line)}figure img{max-width:100%;display:block;margin:auto;cursor:zoom-in}figcaption{font-size:11px;line-height:1.85;color:var(--muted);margin-top:12px}figcaption p{margin:7px 0}.table-wrap{padding:18px 15px;border-top:1px solid var(--line);overflow-x:auto}.table-wrap table{border-collapse:collapse;width:100%;font-size:10px;white-space:nowrap}.table-wrap caption{font-size:12px;font-weight:600;text-align:left;margin-bottom:10px;white-space:normal}.table-wrap th,.table-wrap td{border:1px solid #deddd6;padding:7px;text-align:left}.table-wrap th{background:#edf1f4;color:#33475a}.table-wrap .table-note{font-size:11px;color:var(--muted);white-space:normal;margin:9px 0 0}.argument-map{margin-top:45px}.flow{display:grid;grid-template-columns:repeat(5,1fr);gap:12px}.flow-step{border-top:4px solid var(--accent);border-left:1px solid var(--line);border-right:1px solid var(--line);border-bottom:1px solid var(--line);background:#fffdf9;padding:16px}.flow-step h3{font-size:14px;margin:0 0 9px}.flow-step p{font-size:12px;line-height:1.9;margin:0}.summary-card{padding:18px 22px;border:1px solid var(--line);background:#fffdf9;margin-top:15px}.summary-card h3{font-size:15px;margin:0 0 8px}.summary-card p{font-size:14px;margin:0;line-height:1.95}.comparison{display:grid;grid-template-columns:1fr 1fr;gap:15px}.strong{border-left:4px solid #8bc59b}.weak{border-left:4px solid #e98b82}.claim{border-left:4px solid #f2d66d}.attribution{border-top:1px solid var(--line);margin-top:25px;padding-top:18px;font-size:11px;color:#687383;line-height:1.9}footer{text-align:center;font-size:11px;color:#7e8384;padding:20px;border-top:1px solid var(--line)}dialog{border:1px solid var(--line);max-width:96vw;max-height:96vh;padding:20px;background:#fffdf8}dialog::backdrop{background:#10263fe0}dialog img{max-width:90vw;max-height:80vh;display:block}dialog button{float:right;margin-bottom:12px}body.focus .pair{grid-template-columns:1fr}body.focus .annotation{display:none}body.focus .left-card{max-width:1000px;margin:auto;width:100%}body.focus .column-head{display:none}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}@media(max-width:900px){.pair,.column-head{grid-template-columns:minmax(0,1.1fr) minmax(260px,.9fr)}.flow{grid-template-columns:1fr 1fr}.section-heading{display:block}.section-heading p{margin-top:6px}.annotation{padding:16px}.english{font-size:15px}.passage-top{padding:17px}}@media(max-width:700px){.pair{grid-template-columns:1fr;gap:10px}.column-head{display:none}.annotation{margin-bottom:4px}.comparison{grid-template-columns:1fr}.flow{grid-template-columns:1fr}.site-nav{flex-direction:column;align-items:flex-start;gap:8px}.site-nav div{gap:20px}.paper-top{padding:24px 20px}.nav-inner{padding:0 10px}main{padding:20px 14px}.section-nav a{padding:12px 8px}.passage-top{padding:17px 18px}.translation{padding:14px 18px 15px 21px}.section-heading h2{font-size:20px}.legend{gap:9px 13px;font-size:11px}.paper-actions{gap:8px}.passage-label{flex-direction:column;gap:4px}.flow-step{padding:14px}}@media print{.site-nav,.section-nav,.paper-actions,dialog{display:none!important}.paper-top{background:white;color:black;border-bottom:2px solid #888}.course,.citation,.kicker{color:#444}.legend{border-top:1px solid #aaa}body{background:white}.pair{break-inside:avoid;display:grid;grid-template-columns:1.18fr .82fr;gap:12px}.english{font-size:10pt}.translation{font-size:9pt}.annotation p{font-size:8.5pt}.flow{grid-template-columns:repeat(5,1fr)}main{padding:0}.paper-top{padding:0 0 15px}mark{print-color-adjust:exact;-webkit-print-color-adjust:exact}.translation,.annotation{print-color-adjust:exact;-webkit-print-color-adjust:exact}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
'''
SCRIPT="""(()=>{const links=[...document.querySelectorAll('.section-nav a')];const o=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)links.forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id))}),{rootMargin:'-8% 0px -75% 0px'});document.querySelectorAll('main>section').forEach(s=>o.observe(s));document.querySelector('#mode')?.addEventListener('change',e=>document.body.classList.toggle('focus',e.target.value==='focus'));document.querySelector('#print')?.addEventListener('click',()=>window.print());const d=document.querySelector('dialog');document.querySelectorAll('figure img').forEach(i=>{const open=()=>{d.querySelector('img').src=i.src;d.querySelector('img').alt=i.alt;d.showModal()};i.addEventListener('click',open);i.addEventListener('keydown',e=>{if(e.key==='Enter')open()})});d.querySelector('button').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d)d.close()})})();"""
def marked(b):
    text=b['english'];spans=[]
    for h in b.get('highlights',[]):
        start=text.find(h['text']);spans.append((start,start+len(h['text']),h['kind']))
    parts=[];end=0
    for a,z,k in sorted(spans):parts.extend((e(text[end:a]),'<mark class="'+k+'">'+e(text[a:z])+'</mark>'));end=z
    parts.append(e(text[end:]));return ''.join(parts).replace('\n','<br>')
def render_html(n,root,embedded=True,site_prefix=None):
    root=Path(root);validate(n,root);sections=[];number=0
    for i,s in enumerate(n['sections'],1):
        blocks=[]
        for b in s['blocks']:
            number+=1;figures='';tables=''
            for f in b.get('figures',[]):
                if embedded:
                    mime=mimetypes.guess_type(f['path'])[0] or 'image/jpeg';src='data:'+mime+';base64,'+base64.b64encode((root/f['path']).read_bytes()).decode()
                else:src=(site_prefix or '../')+f['path']
                figures+=f'<figure><img src="{e(src)}" alt="{e(f["alt"])}" loading="lazy" tabindex="0" role="button" aria-label="放大：{e(f["alt"])}"><figcaption>{p(f["caption"])}<a href="{e(f["source"])}">原图出处 ↗</a> · {e(f["license"])}</figcaption></figure>'
            for t in b.get('tables',[]):
                best={tuple(pair)for pair in t.get('bestCells',[])}
                rows=''.join('<tr>'+''.join('<td>'+('<strong>'+e(c)+'</strong>'if (ri,ci)in best else e(c))+'</td>' for ci,c in enumerate(row))+'</tr>' for ri,row in enumerate(t['rows']))
                tables+='<div class="table-wrap"><table><caption>'+e(t['caption'])+'</caption><thead><tr>'+''.join('<th scope="col">'+e(h)+'</th>' for h in t['headers'])+'</tr></thead><tbody>'+rows+'</tbody></table><p class="table-note">'+e(t.get('note',''))+'</p></div>'
            a=b['annotation'];kind=b.get('highlights',[{'kind':'method'}])[0]['kind'] if b.get('highlights') else 'method'
            blocks.append(f'<article class="pair" id="p{number:02d}"><div class="left-card"><div class="passage-top"><div class="passage-label"><span>{e(b["sourceLocation"])}</span><span>段落单元 {number:02d}</span></div><h3 class="passage-title">{e(b["heading"])}</h3><div class="english" lang="en">{marked(b)}</div></div><div class="translation" lang="zh-CN"><span class="translation-label">中文译文 · 对应上方原文</span>{p(b["translation"])}</div>{figures}{tables}</div><aside class="annotation" style="--accent:var(--{kind})"><div class="function">段落功能｜{e(a["function"])}</div><h4>逻辑角色</h4>{p(a["role"])}<h4>论证技巧 / 潜在漏洞</h4>{p(a["critique"])}<div class="explain"><h4>展开讲解 · AI 辅助</h4>{p(b["explanation"])}</div><p class="source-note">对应位置：{e(b["sourceLocation"])}</p></aside></article>')
        sections.append(f'<section id="{e(s["id"])}"><div class="section-heading"><h2>{i:02d} · {e(s["originalHeading"])}｜{e(s["title"])}</h2><p>{e(s["sourceLocation"])}</p></div><div class="column-head"><div>英文原文 → 中文译文</div><div>逐段中文批注 → 深入讲解</div></div>{"".join(blocks)}</section>')
    am=n['argumentMap'];steps=[('problem','问题','thesis'),('thesis','论点','thesis'),('evidence','证据','evidence'),('rebuttal','反驳 / 限定','concession'),('conclusion','结论','method')]
    flow=''.join(f'<div class="flow-step" style="--accent:var(--{kind})"><h3>{i:02d} · {label}</h3>{p(am[key])}</div>' for i,(key,label,kind) in enumerate(steps,1))
    argument=f'<section id="argument-map" class="argument-map"><div class="section-heading"><h2>论证结构总览</h2><p>问题 → 论点 → 证据 → 反驳 → 结论</p></div><div class="flow">{flow}</div><div class="summary-card claim"><h3>作者核心主张｜一句话版本</h3>{p(am["claim"])}</div><div class="comparison"><div class="summary-card strong"><h3>论证最强处</h3>{p(am["strongest"])}</div><div class="summary-card weak"><h3>论证最弱处</h3>{p(am["weakest"])}</div></div></section>'
    nav=''.join('<a href="#'+e(s['id'])+'">'+e(s['title'])+'</a>' for s in n['sections'])+'<a href="#argument-map">论证总览</a>'
    legend=''.join(f'<span><i class="swatch" style="background:var(--{k})"></i>{v}</span>' for k,v in LABELS.items())
    sitenav=f'<nav class="site-nav" aria-label="站点导航"><a href="{site_prefix}index.html"><strong>SALINE PAPERS</strong></a><div><a href="{site_prefix}index.html">论文库</a><a href="{site_prefix}guide.html">阅读与发布</a><a href="{site_prefix}admin.html">管理</a><a href="https://github.com/ch3ndl/paper">GitHub ↗</a></div></nav>' if site_prefix else '<nav class="site-nav"><strong>SALINE PAPERS · 论文双语精读</strong><a href="https://ch3ndl.github.io/paper/">返回论文库 ↗</a></nav>'
    download=f'<a href="{site_prefix}downloads/{e(n["slug"])}.html" download>下载完整双栏 HTML ↓</a><a href="{site_prefix}notes/{e(n["slug"])}.json" download>笔记数据 JSON ↓</a>' if site_prefix else ''
    css=STYLE.replace('</style','<\\/style');script=SCRIPT
    return f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{e(n['summary'])}"><title>{e(n['title'])}｜英中双栏论证精读</title><style>{css}</style></head><body>{sitenav}<header class="paper-top"><div class="kicker">BILINGUAL CLOSE READING · ARGUMENT ANNOTATION</div><h1>{e(n.get('subtitle') or n['title'])}</h1><p class="course">{e(n['course'])}</p><p class="citation">{e(n['source']['citation'])}</p><div class="meta"><span>{e(n['category'])}</span><span>{n['year']}</span><span>英文据原文核对 · 中文为译文与 AI 批注</span></div><div class="paper-actions"><a href="{e(n['source']['url'])}">阅读原文 ↗</a>{download}<button id="print" type="button">打印 / PDF</button><label class="sr-only" for="mode">阅读布局</label><select id="mode"><option value="annotated">双栏批注</option><option value="focus">专注原文与译文</option></select></div><div class="legend" aria-label="五色分析图例">{legend}</div></header><nav class="section-nav" aria-label="章节导航"><div class="nav-inner">{nav}</div></nav><main><div class="notice">阅读范围与来源：{e(n['coverage'])}</div><div class="overview"><strong>先抓住主线：</strong>{e(n['summary'])}</div>{''.join(sections)}{argument}<div class="attribution"><strong>论文与许可：</strong>{e(n['source']['citation'])}<br>{e(n['source']['license'])}<br>英文来自原文；中文译文、讲解、批注与高亮为阅读辅助，均非原论文新增结论。更新：{e(n['updated'])}。课程栏目：{e(n['course'])}。</div></main><footer>Saline Papers · Bilingual Argument Annotation</footer><dialog aria-label="论文图片放大"><button type="button">关闭 ×</button><img alt=""></dialog><script>{script}</script></body></html>'''
if __name__=='__main__':
    if len(sys.argv)!=4:raise SystemExit('Usage: render_note.py NOTE.json EXPORT_ROOT OUTPUT.html')
    path,root,out=sys.argv[1:];n=json.loads(Path(path).read_text(encoding='utf-8'));Path(out).write_text(render_html(n,root),encoding='utf-8');print('Rendered standalone bilingual HTML:',out)
